import copy,sys,unittest
from pathlib import Path
from t217_org_loss_certificate import certify,load
Q=Path(__file__).resolve().parent
class OrgCertificateTests(unittest.TestCase):
 def setUp(self): self.d=load(Q/'t217_org_loss_certificate_inputs.json')
 def result(self,cid=3096): return certify(self.d,cid)
 def mutate(self,fn): fn(self.d);self.assertIsNone(self.result())
 def test_actual3096(self):self.assertEqual(self.result()['casualties'],{'our_org_loss':7.52335,'enemy_org_loss':1.71985})
 def test_actual3097(self):self.assertEqual(self.result(3097)['casualties'],{'our_org_loss':0.3657,'enemy_org_loss':1.66155})
 def test_no_manpower_or_strength_output(self):self.assertEqual(set(self.result()['casualties']),{'our_org_loss','enemy_org_loss'})
 def test_reordered_sides_not_swapped(self):self.d['combats'][0]['sides'].reverse();self.assertEqual(self.result()['casualties']['our_org_loss'],7.52335)
 def test_prevented_is_not_added(self):self.d['combats'][0]['sides'][0]['raw']['0x190']=123456789;self.assertEqual(self.result()['casualties']['our_org_loss'],7.52335)
 def test_strength_is_not_added(self):self.d['combats'][0]['sides'][0]['raw']['0x178']=123456789;self.assertEqual(self.result()['casualties']['our_org_loss'],7.52335)
 def test_unknown_combat_out_of_scope(self):self.assertIsNone(self.result(3072))
 def test_bool_id_rejected(self):self.assertIsNone(self.result(True))
 def test_session_change(self):self.mutate(lambda d:d['guard_after'].update(hour_tick=60781106))
 def test_wrong_version(self):self.mutate(lambda d:d.update(version='other'))
 def test_unpaused(self):self.d['guard_before']['pause']=0;self.d['guard_after']['pause']=0;self.assertIsNone(self.result())
 def test_open_gate(self):self.d['guard_before']['markers']['safe_land_tool_gate.OPEN']=True;self.d['guard_after']['markers']['safe_land_tool_gate.OPEN']=True;self.assertIsNone(self.result())
 def test_empty_markers_not_closed_proof(self):self.d['guard_before']['markers']={};self.d['guard_after']['markers']={};self.assertIsNone(self.result())
 def test_wrong_scale(self):self.mutate(lambda d:d['scale'].update(fixed=1000))
 def test_scale_source_change(self):self.mutate(lambda d:d['scale'].update(input_observation_sha256='0'*64))
 def test_unresolved_cfg(self):self.mutate(lambda d:d['native']['ground_apply_caller']['unresolved_edges'].append({'address':'unknown'}))
 def test_missing_actual_delta_instruction(self):self.mutate(lambda d:d['native']['ground_apply_caller']['asm'].remove('1343794 add qword ptr [r8 + 0x180], rax'))
 def test_no_birth_parent_proof(self):self.mutate(lambda d:d['native']['base_ctor']['asm'].remove('147c360 mov qword ptr [rcx + 0x18], rdx'))
 def test_no_zero_initialization(self):self.mutate(lambda d:d['native']['side_ctor']['asm'].remove('133a286 mov qword ptr [rsi + 0x180], rbp'))
 def test_wrong_keyword(self):self.mutate(lambda d:d['names'].update({'0x374a':'manpower_lost'}))
 def test_wrong_parent(self):self.mutate(lambda d:d['combats'][0]['sides'][0].update(parent='0x1'))
 def test_wrong_forward_binding(self):self.mutate(lambda d:d['combats'][0]['sides'][0].update(forward_offset='0x30'))
 def test_wrong_side_rtti(self):self.mutate(lambda d:d['combats'][0]['sides'][0].update(**{'class':'.?AVCBorderCombatant@@'}))
 def test_wrong_combat_handle(self):self.mutate(lambda d:d['combats'][0].update(handle_type=51))
 def test_extended_handle_not_blanket_admitted(self):self.mutate(lambda d:d['combats'][0]['sides'][0]['members'][0].update(type=4713))
 def test_ambiguous_own_membership(self):self.mutate(lambda d:d['own_units'].remove(d['combats'][0]['sides'][0]['members'][0]['ptr']))
 def test_duplicate_member(self):self.mutate(lambda d:d['combats'][0]['sides'][1]['members'].append(copy.deepcopy(d['combats'][0]['sides'][0]['members'][0])))
 def test_nonzero_air_outside_positive_coverage(self):self.mutate(lambda d:d['combats'][0]['sides'][0]['raw'].update({'0x170':1}))
 def test_negative_org_counter(self):self.mutate(lambda d:d['combats'][0]['sides'][0]['raw'].update({'0x180':-1}))
 def test_zero_not_positive_proof(self):self.mutate(lambda d:d['combats'][0]['sides'][0]['raw'].update({'0x180':0}))
 def test_bool_counter_rejected(self):self.mutate(lambda d:d['combats'][0]['sides'][0]['raw'].update({'0x180':True}))
 def test_duplicate_combat(self):self.mutate(lambda d:d['combats'].append(copy.deepcopy(d['combats'][0])))
 def test_unstable_dependencies(self):self.mutate(lambda d:d.update(stable_dependencies=0))
 def test_not_full_capture(self):self.assertIs(self.d['production_capture_run'],False);self.assertIs(self.d['complete_input'],False)
if __name__=='__main__':unittest.main()
